solutions.naive:
class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0
        for i in range(n):
            for j in range(i, n):
                seen = set()
                for p in range(i, j + 1):
                    seen.add(s[p])
                if len(seen) == 3:
                    ans += 1
        return ans

solutions.better:
class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0
        for i in range(n):
            count = {'a': 0, 'b': 0, 'c': 0}
            have = 0
            for j in range(i, n):
                if count[s[j]] == 0:
                    have += 1
                count[s[j]] += 1
                if have == 3:
                    ans += n - j
                    break
        return ans

solutions.optimal:
class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        last = {'a': -1, 'b': -1, 'c': -1}
        ans = 0
        for i, ch in enumerate(s):
            last[ch] = i
            earliest = min(last['a'], last['b'], last['c'])
            if earliest != -1:
                ans += earliest + 1
        return ans

